data_t neuron(const data_t in[], const data_t w[], data_t bias, int n, bool do_relu)
{
	data_t acc = bias;

neuron_mac:
	for (int i = 0; i < n; i++) {
		acc += in[i] * w[i];
	}

	if (do_relu && acc < (data_t)0)
		acc = (data_t)0;

	return acc;
}

void mlp(const data_t input[IN_SIZE], data_t output[OUT_SIZE])
{
	data_t a1[L1_SIZE];   /* layer 1 activations */
	data_t a2[L2_SIZE];   /* layer 2 activations */
	data_t a3[L3_SIZE];   /* layer 3 activations */
	data_t z4[OUT_SIZE];  /* output-layer logits (pre-softmax) */

layer1:
	for (int j = 0; j < L1_SIZE; j++)
		a1[j] = neuron(input, W1[j], B1[j], IN_SIZE, true);

layer2:
	for (int j = 0; j < L2_SIZE; j++)
		a2[j] = neuron(a1, W2[j], B2[j], L1_SIZE, true);

layer3:
	for (int j = 0; j < L3_SIZE; j++)
		a3[j] = neuron(a2, W3[j], B3[j], L2_SIZE, true);

layer4:
	for (int j = 0; j < OUT_SIZE; j++)
		z4[j] = neuron(a3, W4[j], B4[j], L3_SIZE, false);

	data_t maxv = z4[0];
softmax_max:
	for (int j = 1; j < OUT_SIZE; j++)
		if (z4[j] > maxv)
			maxv = z4[j];

	data_t sum = (data_t)0;
softmax_exp:
	for (int j = 0; j < OUT_SIZE; j++) {
		data_t e = (data_t)expf((float)(z4[j] - maxv));
		output[j] = e;
		sum += e;
	}

softmax_norm:
	for (int j = 0; j < OUT_SIZE; j++)
		output[j] = output[j] / sum;
}
